import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第七十一章 灭除痛苦的过程","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/71第七十一章 灭除痛苦的过程.md","filePath":"meditation/巴利文大藏经/71第七十一章 灭除痛苦的过程.md"}'),r={name:"meditation/巴利文大藏经/71第七十一章 灭除痛苦的过程.md"};function _(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第七十一章-灭除痛苦的过程" tabindex="-1">第七十一章 灭除痛苦的过程 <a class="header-anchor" href="#第七十一章-灭除痛苦的过程" aria-label="Permalink to &quot;第七十一章 灭除痛苦的过程&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部12相应43经/苦经(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如来将要给你们讲说痛苦聚集、出现的过程；痛苦灭尽、消失的过程。你们要认真的听，你们要仔细的思考，如来现在要开始说法了。”</p><p>出家弟子们回答：“世尊，我们会认真听您说法的，我们会认真的思考的，恭请世尊您为我们说法。”</p><p>佛陀说：“弟子们，痛苦是如何聚集、出现的呢？</p><p>眼睛与事物相遇的时候，通过光线的传递就会产生眼识，什么是眼识呢？</p><p>就是认识、分别、判断外界的事物。</p><p>当眼睛、事物（通过光线传递）、眼识三者汇合、和合的时候，就会产生触。什么是触呢？</p><p>就是对外界事物的认知。</p><p>弟子们也就是说：当眼睛与事物相遇的时候，通过光线的传递就会分别出外界事物的存在和不同，并且产生对外界事物的认知。</p><p>眼识与触有什么区别呢？</p><p>眼识是分别、判断事物的有无、不同。而触是直接确定和认知事物。也就是眼睛与事物相遇，通过光线传递，就会分别各种事物光线的不同，最后确定认知自己看见的事物。</p><p>以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」，弟子们，这就是痛苦聚集、出现的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>耳朵与声音相遇的时候，通过各种介质的传递就会产生耳识。什么是耳识呢？就是认识、分别、判断外界发出的声响。当耳朵、声音（通过各种介质传递）、耳识三者汇合、和合的时候，就会产生触。什么是触呢？就是对外界声音的认知。弟子们也就是说：当耳朵与声音相遇的时候，通过各种介质的传递就会分别出外界声音的存在和不同，并且产生对外界声音的认知。耳识与触有什么区别呢？耳识是分别、判断声音的有无、不同。而触是直接确定和认知声音。也就是耳朵与声音相遇，通过各种介质传递，就会分别出各种不同的声音，最后确定认知自己听见的声音。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」，弟子们，这就是痛苦聚集、出现的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>鼻子与气味相遇的时候，通过各种介质的传递就会产生鼻识。什么是鼻识呢？就是认识、分别、判断外界散发出的气味。当鼻子、气味（通过各种介质传递）、鼻识三者汇合、和合的时候，就会产生触。什么是触呢？就是对外界气味的认知。弟子们也就是说：当鼻子与气味相遇的时候，通过各种介质的传递就会分别出外界气味的存在和不同，并且产生对外界气味的认知。鼻识与触有什么区别呢？鼻识是分别、判断气味的有无、不同。而触是直接确定和认知气味。也就是鼻子与气味相遇，通过各种介质传递，就会分别出各种不同的气味，最后确定认知自己闻到的气味。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」，弟子们，这就是痛苦聚集、出现的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>舌头与味道相遇的时候，就会产生舌识，什么是舌识呢？就是认识、分别、判断外界事物的味道。当舌头、味道、舌识三者汇合、和合的时候，就会产生触，什么是触呢？就是对外界味道的认知。弟子们也就是说：当舌头与味道相遇的时候，就会分别出外界味道的存在和不同，并且产生对外界味道的认知。舌识与触有什么区别呢？舌识是分别、判断味道的有无、不同。而触是直接确定和认知味道。也就是舌头与味道相遇，就会分别出各种不同的味道，最后确定认知自己尝到的味道。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」，弟子们，这就是痛苦聚集、出现的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>身体触摸到事物的时候，就会产生身识，什么是身识呢？就是认识、分别、判断外界事物的触摸感觉。当身体、触觉、身识三者汇合、和合的时候，就会产生触，什么是触呢？就是对外界事物触摸感觉的认知。弟子们也就是说：当身体触摸到事物的时候，就会分别出外界事物触摸感觉的存在和不同，并且产生对外界事物触摸感觉的认知。身识与触有什么区别呢？身识是分别、判断事物触摸感觉的有无、不同。而触是直接确定和认知触觉。也就是身体触摸到事物的时候，就会分别出各种不同的触摸感觉，最后确定认知自己摸到事物的触摸感觉。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」，弟子们，这就是痛苦聚集、出现的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>内心与物质事物、精神思想相遇的时候，就会产生意识，什么是意识呢？就是认识、分别、判断外界物质事物、精神思想。当内心，物质事物、精神思想，意识三者汇合、和合的时候，就会产生触，什么是触呢？就是内心对外界物质事物、精神思想的认知。弟子们也就是说：当内心与物质事物、精神思想相遇的时候，就会分别出外界物质事物、精神思想的存在和不同，并且产生对外界物质事物、精神思想的认知开始思索。意识与触有什么区别呢？意识是分别、判断物质事物、精神思想的有无、不同。而触是直接确定和认知物质事物、精神思想后开始思索。也就是内心与物质事物、精神思想相遇，就会分别出各种不同的物质事物、精神思想，最后确定认知自己接触的物质事物、精神思想开始思索。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」，弟子们，这就是痛苦聚集、出现的过程。这就是缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>弟子们，痛苦要如何才能灭除、灭尽呢？眼睛与事物相遇的时候，通过光线的传递就会产生眼识。当眼睛、事物（通过光线传递）、眼识三者汇合、和合的时候，就会产生触。弟子们也就是说：当眼睛与事物相遇的时候，通过光线的传递就会分别出外界事物的存在和不同，并且产生对外界事物的认知。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」。当「贪爱」逐渐褪去、消除、灭尽的时候，那么「取」就会消除、灭尽。「取」灭尽了，「有」就会灭尽。「有」灭尽了，「生」就会灭尽。「生」灭尽了，愁闷、悲伤、痛苦、忧虑、绝望、衰老、死亡就灭尽了，这就是痛苦灭除、灭尽的过程。弟子们，这就是痛苦灭除的修行方法。</p><p>耳朵与声音相遇的时候，通过各种介质的传递就会产生耳识。当耳朵、声音（通过各种介质传递）、耳识三者汇合、和合的时候，就会产生触。弟子们也就是说：当耳朵与声音相遇的时候，通过各种介质的传递就会分别出外界声音的存在和不同，并且产生对外界声音的认知。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」。当「贪爱」逐渐褪去、消除、灭尽的时候，那么「取」就会消除、灭尽。「取」灭尽了，「有」就会灭尽。「有」灭尽了，「生」就会灭尽。「生」灭尽了，愁闷、悲伤、痛苦、忧虑、绝望、衰老、死亡就灭尽了，这就是痛苦灭除、灭尽的过程。弟子们，这就是痛苦灭除的修行方法。</p><p>鼻子与气味相遇的时候，通过各种介质的传递就会产生鼻识。当鼻子、气味（通过各种介质传递）、鼻识三者汇合、和合的时候，就会产生触。弟子们也就是说：当鼻子与气味相遇的时候，通过各种介质的传递就会分别出外界气味的存在和不同，并且产生对外界气味的认知。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」。当「贪爱」逐渐褪去、消除、灭尽的时候，那么「取」就会消除、灭尽。「取」灭尽了，「有」就会灭尽。「有」灭尽了，「生」就会灭尽。「生」灭尽了，愁闷、悲伤、痛苦、忧虑、绝望、衰老、死亡就灭尽了，这就是痛苦灭除、灭尽的过程。弟子们，这就是痛苦灭除的修行方法。</p><p>舌头与味道相遇的时候，就会产生舌识。当舌头、味道、舌识三者汇合、和合的时候，就会产生触。弟子们也就是说：当舌头与味道相遇的时候，就会分别出外界味道的存在和不同，并且产生对外界味道的认知。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」。当「贪爱」逐渐褪去、消除、灭尽的时候，那么「取」就会消除、灭尽。「取」灭尽了，「有」就会灭尽。「有」灭尽了，「生」就会灭尽。「生」灭尽了，愁闷、悲伤、痛苦、忧虑、绝望、衰老、死亡就灭尽了，这就是痛苦灭除、灭尽的过程。弟子们，这就是痛苦灭除的修行方法。</p><p>身体触摸到事物的时候，就会产生身识。当身体、触觉、身识三者汇合、和合的时候，就会产生触。弟子们也就是说：当身体触摸到事物的时候，就会分别出外界事物触摸感觉的存在和不同，并且产生对外界事物触摸感觉的认知。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」。当「贪爱」逐渐褪去、消除、灭尽的时候，那么「取」就会消除、灭尽。「取」灭尽了，「有」就会灭尽。「有」灭尽了，「生」就会灭尽。「生」灭尽了，愁闷、悲伤、痛苦、忧虑、绝望、衰老、死亡就灭尽了，这就是痛苦灭除、灭尽的过程。弟子们，这就是痛苦灭除的修行方法。</p><p>内心与物质事物、精神思想相遇的时候，就会产生意识。当内心，物质事物、精神思想，意识三者汇合、和合的时候，就会产生触。弟子们也就是说：当内心与物质事物、精神思想相遇的时候，就会分别出外界物质事物、精神思想的存在和不同，并且产生对外界物质事物、精神思想的认知开始思索。以「触」为前提条件就会产生各种「感受」，以「感受」为前提条件就会产生「贪爱」。当「贪爱」逐渐褪去、消除、灭尽的时候，那么「取」就会消除、灭尽。「取」灭尽了，「有」就会灭尽。「有」灭尽了，「生」就会灭尽。「生」灭尽了，愁闷、悲伤、痛苦、忧虑、绝望、衰老、死亡就灭尽了，这就是痛苦灭除、灭尽的过程。弟子们，这就是痛苦灭除的修行方法。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',26)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
